class Solution {
  public int smallestFactorization(int num) {
    if (num < 10) return num;
    long result = 0, place = 1;
    for (int d = 9; d >= 2; d--) {
      while (num % d == 0) {
        num /= d;
        result += d * place;
        place *= 10;
        if (result > Integer.MAX_VALUE) return 0;
      }
    }
    return num == 1 ? (int) result : 0;
  }
}
